// ---------------------------------------------------------------------------
// Hourly Paycheck Calculator — SEO content
// ---------------------------------------------------------------------------
// Worked examples are generated by calculatePaycheck(), the same engine the
// calculator runs, so the numbers in the article always match the tool.

import {
  calculatePaycheck,
  FEDERAL_STANDARD_DEDUCTION,
  SOCIAL_SECURITY_WAGE_BASE,
  TAX_YEAR,
  type FilingStatus,
  type PaycheckInput,
  type PayFrequency,
} from '@/lib/payroll/withholding-2026';
import { STATE_CODES, STATE_PAYCHECK_PAGES } from '@/lib/payroll/state-pages';

const usd = (n: number) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
const pct = (n: number) => `${(n * 100).toFixed(1)}%`;

const FREQ_WORD: Record<PayFrequency, string> = {
  weekly: 'weekly',
  'bi-weekly': 'every two weeks',
  'semi-monthly': 'twice a month',
  monthly: 'monthly',
};

const STATUS_WORD: Record<FilingStatus, string> = {
  single: 'single',
  married: 'married filing jointly',
  hoh: 'head of household',
};

interface Scenario {
  title: string;
  where: string;
  input: PaycheckInput;
}

function describe(s: Scenario) {
  const r = calculatePaycheck(s.input);
  const { hourlyRate, regularHoursPerWeek: reg, overtimeHoursPerWeek: ot, payFrequency, filingStatus } = s.input;
  const hours = ot > 0 ? `${reg} regular hours plus ${ot} overtime hours a week` : `${reg} hours a week`;
  const lines = r.deductions.map((d) => `${d.label} ${usd(d.perPeriod)}`).join(', ');
  return {
    title: s.title,
    description:
      `${usd(hourlyRate)} an hour for ${hours}, paid ${FREQ_WORD[payFrequency]}, filing ${STATUS_WORD[filingStatus]}, ${s.where}. ` +
      `Gross pay is ${usd(r.grossPerPeriod)} per paycheck (${usd(r.grossAnnual)} a year). ` +
      `Withheld per paycheck: ${lines}. ` +
      `Take-home pay: ${usd(r.netPerPeriod)} per paycheck, or ${usd(r.netAnnual)} a year, which works out to ${usd(r.netPerHour)} per hour worked. ` +
      `Deductions take ${pct(r.effectiveRate)} of gross pay.`,
  };
}

